friends = [
    {
        'name': 'David',
        'location': "Fisherman's Wharf",
        'avail_start': 10 * 60 + 45,   # 10:45 AM
        'avail_end': 15 * 60 + 30,     # 3:30 PM
        'meet_min': 15,
    },
    {
        'name': 'Timothy',
