        'meet_min': 90,
    },
]

def fmt(t):
    # t minutes from midnight -> e.g., 9:13AM
    hour24 = t // 60
    minute = t % 60
    suffix = 'AM' if hour24 < 12 else 'PM'
    hour12 = hour24 % 12
    if hour12 == 0:
        hour12 = 12
    return f"{hour12}:{minute:02d}{suffix}"

def try_order(order):
    steps = []
    cur_loc = 'Financial District'
    cur_time = 9 * 60  # 9:00 AM
    steps.append(f"You start at {cur_loc} at {fmt(cur_time)}.")
    for fr in order:
        # travel
        travel_time = travel[cur_loc][fr['location']]
        arr_time = cur_time + travel_time
        steps.append(f"You travel to {fr['location']} in {travel_time} minutes and arrive at {fmt(arr_time)}.")
        # wait if early
        meet_start = max(arr_time, fr['avail_start'])
        if meet_start > arr_time:
            steps.append(f"You wait until {fmt(meet_start)}.")
        meet_end = meet_start + fr['meet_min']
        if meet_end > fr['avail_end']:
            return None  # infeasible
        steps.append(f"You meet {fr['name']} from {fmt(meet_start)} to {fmt(meet_end)}.")
        cur_loc = fr['location']
        cur_time = meet_end
    return steps

best = None
best_len = -1
best_finish = None

for r in range(len(friends), 0, -1):
    for perm in itertools.permutations(friends, r):
        itinerary = try_order(perm)
        if itinerary is None:
            continue
        if r > best_len or (r == best_len and (best_finish is None or cur_time < best_finish)):
            best = itinerary
            best_len = r
            best_finish = cur_time
    if best_len == r:
        break  # found optimum with maximum possible friends

print(best)
